// Build-time only: evaluates the pinned original pilot rig dressing on real source rigs: weapon-visuals.ts bodyModifiers (the
// body chips), ranged-vfx.ts spellCharge and spellMotes, block-cooldown-tint.ts BlockCooldownTint, the class base offsets
// poseFirstPersonView writes (first-person-view.ts) and the Siren's weapon socket after buildSiren (siren/model.ts). The expected
// values are never generated by the C# port.
// Usage: node tools/export_rig_dressing_fixtures.mjs <pinned source checkout with node_modules> <temporary output directory>
// Writes Tests/rig-dressing-parity.json.
import fs from 'node:fs';import path from 'node:path';import {fileURLToPath,pathToFileURL} from 'node:url';import {stripTypeScriptTypes} from 'node:module';import {createHash} from 'node:crypto';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'),source=path.resolve(process.argv[2]),temp=path.resolve(process.argv[3]);
const inventory=JSON.parse(fs.readFileSync(path.join(root,'tools/conversion-inventory.json')));
fs.mkdirSync(temp,{recursive:true});fs.writeFileSync(path.join(temp,'package.json'),'{"type":"module"}');
// Same verified transpile as tools/export_weapon_fixtures.mjs: every source blob must match the inventory receipt.
for(const f of inventory.files.filter(f=>f.path.startsWith('src/')&&f.path.endsWith('.ts'))){const input=path.join(source,f.path);if(!fs.existsSync(input))continue;const b=fs.readFileSync(input);if(createHash('sha1').update(`blob ${b.length}\0`).update(b).digest('hex')!==f.gitBlob)throw Error('Source mismatch '+f.path);const out=path.join(temp,f.path.replace(/\.ts$/,'.js'));fs.mkdirSync(path.dirname(out),{recursive:true});let code=b.toString().replace(/import\s*\{([^}]+)\}\s*from\s*(['"])([^'"]+)\2/g,(whole,names,quote,module)=>{if(!module.startsWith('.'))return whole;let target=path.resolve(path.dirname(input),module.replace(/\.js$/,'.ts'));if(!fs.existsSync(target))return whole;let text=fs.readFileSync(target,'utf8'),kept=names.split(',').filter(n=>!new RegExp('(?:export\\s+)?(?:interface|type)\\s+'+n.trim().split(/\s+as\s+/)[0]+'\\b').test(text));return kept.length?'import {'+kept.join(',')+'} from '+quote+module+quote:'import '+quote+module+quote;});fs.writeFileSync(out,stripTypeScriptTypes(code,{mode:'transform'}));}
if(!fs.existsSync(path.join(temp,'node_modules')))fs.symlinkSync(path.join(source,'node_modules'),path.join(temp,'node_modules'),'dir');
const T=await import(pathToFileURL(path.join(temp,'node_modules/three/build/three.module.js')));const load=p=>import(pathToFileURL(path.join(temp,'src',p+'.js')));
const {createCharacterRig}=await load('client/character-rig'),{buildWeapon,weaponModifiers,enchantWeapon,bodyModifiers}=await load('client/weapon-visuals');
const {spellCharge,spellMotes}=await load('client/ranged-vfx'),{BlockCooldownTint}=await load('client/block-cooldown-tint'),{spellPose}=await load('client/character-animation');
const {abilityPhrase}=await load('client/ranged-motion'),{poseFirstPersonView,FP_TUNE}=await load('client/first-person-view'),{markFirstPersonRig}=await load('client/pose-flags');
const {sirenify}=await load('client/siren/index'),{statsFor,WEAPONS,CHIPS,castWindup}=await load('shared/content'),{ARCADE}=await load('shared/arcade-content');
const r6=x=>Math.round(x*1e6)/1e6,arr=v=>v.toArray().map(r6);const ids=new Set(CHIPS.map(c=>c.id));
const check=chips=>{for(const id of Object.keys(chips))if(!ids.has(id))throw Error('Unknown chip '+id);return chips;};
const shape=g=>g.type==='BoxGeometry'?'cube':g.type==='SphereGeometry'?'sphere':g.type==='ConeGeometry'?'cone':g.type==='TorusGeometry'?'ring':g.type;
const piece=o=>({shape:shape(o.geometry),glow:o.material.type==='MeshBasicMaterial',shadow:o.castShadow,color:o.material.color.getHex(),visible:o.visible,p:arr(o.position),q:arr(o.quaternion),s:arr(o.scale)});
const pilot=(spec,extra={})=>({id:'pilot-'+spec,spec,color:'#70e1d0',hp:100,pos:{x:0,y:.865,z:0},vel:{x:0,y:0,z:0},yaw:0,pitch:0,grounded:true,dashTime:0,sprinting:false,lastAttack:-10,lastShot:-10,attackRate:1,attackIndex:0,
 chips:{},guarding:false,blockTime:0,blockCd:0,lastBlock:-10,hitStunUntil:0,reach:WEAPONS[spec].range,stats:{},reloadTime:0,weaponAway:false,lastSecondary:-1e9,ammo:10,...extra});
// 1. Body chips (bodyModifiers) per loadout, after the per-frame orbit and dash-jet update at `time`. Each piece is recorded in
// the frame of the joint its 'body-chips' socket hangs from (the socket sits at the joint origin; read as the joint's own child,
// since r.chest.getObjectByName('body-chips') reaches the left upper arm's socket first).
const PARENTS=['chest','leftArm','rightArm','leftFoot','rightFoot'];
const BODY_STATS=['maxMana','maxStamina','knockbackTaken','debrisTaken','dashCooldown','blockForce','blockHeal','blockAmmo','blockCooldown','blockWindow','reflectDamage','blockPulseDamage'];
const bodyCases=[
 ['sword',{}],['sword',{vital:8,frame:1,stamina:3,dash:1,stabilizer:1,'block-recharge':1}],['fire',{mana:2,'arcane-ward':1,salvage:2,thorns:1}],
 ['greatsword',{juggernaut:1,endurance:1,recycler:1,comet:1}],['pistol',{fortress:1,'block-loader':1,rubber:1,'reserve-cell':1}],['emperor',{bulwark:1,vital:2,skirmisher:1}],
 ['siren',{'siren-hide':1,vital:3}],['ansatsuken',{supernova:1,'block-pulse':1,counterweight:1,dash:2}],['darkness',{mana:8,reservoir:2}],['leet',{anchor:1,salvage:1,'block-window':1}],
 ['rifle',{rubber:1,'block-return':1,'tumble-engine':1}],['daggers',{'block-medic':1,stamina:1,vital:1}],['shield',{rebound:1,quickguard:1,stamina:9}],['water',{'arcane-overflow':1,repulsor:1}]];
const body=[];for(const [spec,chips] of bodyCases){check(chips);const rig=createCharacterRig('#70e1d0',undefined,true);const s=statsFor(chips);
 for(const [time,dash] of [[0,0],[.73,.12],[2.2,0],[5.31,.04]]){bodyModifiers(rig,pilot(spec,{chips,dashTime:dash}),time);const pieces={};
  for(const name of PARENTS){const g=rig[name].children.find(o=>o.name==='body-chips');pieces[name]=g?g.children.map(piece):[];}
  body.push({spec,chips,time,dashTime:dash,stats:Object.fromEntries(BODY_STATS.map(k=>[k,r6(s[k])])),pieces});}}
// 2. The right-hand spell charge (spellCharge) over primary casts, Q/E phrases and the Ansatsuken's Hadoken charge. The socket
// is recorded in the right-hand joint's frame; each sample keeps the phrase the source chose (an ability phrase needs its id,
// start and release so the native cast fields can be filled the way NativeAbilities writes them). Sample times stay clear of
// the release, release + .08 and phrase-end edges, where the native float clock and the source's double clock may round apart.
const chargeOf=rig=>rig.rightHand.getObjectByName('spell-charge');
const chargeCases=[
 {name:'fire primary',spec:'fire',lastAttack:10,times:[9.99,10,10.012,10.03,10.05,10.1,10.159,10.1601,10.19,10.219,10.221,10.239,10.241,10.3]},
 {name:'water primary at attack rate 1.5',spec:'water',lastAttack:10,attackRate:1.5,times:[10,10.02,10.06,10.079,10.081,10.1,10.13,10.14,10.159,10.161]},
 {name:'lightning primary',spec:'lightning',lastAttack:10,times:[10,10.01,10.05,10.064,10.066,10.1,10.13,10.144,10.146,10.2]},
 {name:'darkness primary at attack rate .6',spec:'darkness',lastAttack:10,attackRate:.6,times:[10,.1+10,10.2,10.36,10.367,10.37,10.4,10.433,10.45,10.5]},
 {name:'leet primary',spec:'leet',lastAttack:10,times:[10,10.05,10.17,10.181,10.2,10.239,10.241,10.262,10.3]},
 {name:'fire Q (flame lance)',spec:'fire',lastAttack:19,lastAbility:20,times:[19.9,20,20.05,20.11,20.1201,20.15,20.179,20.181,20.199,20.201,20.5,23.1]},
 {name:'water E (geyser wall) at attack rate 1.3',spec:'water',lastAttack:19,lastSecondary:20,attackRate:1.3,times:[20,20.1,20.19,20.2,20.25,20.27,20.3,20.4]},
 {name:'darkness Q older than the primary',spec:'darkness',lastAttack:30.2,lastAbility:30,times:[30.25,30.3,30.421,30.43,30.499]},
 {name:'lightning dead mid-cast',spec:'lightning',lastAttack:10,hp:0,times:[10.02,10.05]},
 {name:'sword (melee) swing',spec:'sword',lastAttack:10,times:[10,10.05,10.2]},
 {name:'ansatsuken Hadoken charge',spec:'ansatsuken',lastAttack:-10,arcade:[[40,null,0],[40.2,'charge',0],[40.9,'charge',.5],[41.6,'charge',1],[42,'hadoken',0],[42.5,'charge',.3]]},
 {name:'ansatsuken charge while dead',spec:'ansatsuken',lastAttack:-10,hp:0,arcade:[[41,'charge',.7]]}];
const charge=[];for(const c of chargeCases){const rig=createCharacterRig('#70e1d0',undefined,true);const samples=[];
 const steps=c.arcade?c.arcade.map(([t,action,amount])=>({t,arcade:{action:action??undefined,charge:amount,at:0,until:0,index:0,total:0,uppercutCd:0,hadokenCd:0,hits:0,lastHit:-10,comboDamage:0,parryUntil:0,parryAt:-10}})):c.times.map(t=>({t}));
 for(const step of steps){const p=pilot(c.spec,{hp:c.hp??100,lastAttack:c.lastAttack,attackRate:c.attackRate??1,lastAbility:c.lastAbility,lastSecondary:c.lastSecondary??-1e9,arcade:step.arcade});spellCharge(rig,p,step.t);
  const g=chargeOf(rig),halos=g.children.filter(o=>o.name==='spell-halo'),ab=WEAPONS[c.spec].class==='magic'?abilityPhrase(p,step.t):undefined;
  samples.push({time:step.t,action:step.arcade?.action??null,charge:step.arcade?.charge??0,visible:g.visible,scale:r6(g.scale.x),q:arr(g.quaternion),halos:halos.map(h=>arr(h.quaternion)),
   ability:ab&&ab.start>p.lastAttack?{id:ab.id,start:r6(ab.start),releaseAt:r6(ab.releaseAt)}:null});}
 const g=chargeOf(rig),[orb,...halos]=g.children,start=Math.max(c.lastAbility??-1e9,c.lastSecondary??-1e9),ref=WEAPONS[c.spec].class==='magic'&&start>-1e8?abilityPhrase(pilot(c.spec,{lastAbility:c.lastAbility,lastSecondary:c.lastSecondary??-1e9,attackRate:c.attackRate??1}),start+.001):undefined;
 charge.push({name:c.name,ability:ref?{id:ref.id,start:ref.start,releaseAt:ref.releaseAt}:null,spec:c.spec,hp:c.hp??100,lastAttack:c.lastAttack,attackRate:c.attackRate??1,lastAbility:c.lastAbility??null,lastSecondary:c.lastSecondary??null,
  socket:arr(g.position),orb:piece(orb),halos:halos.map(piece),castWindup:r6(castWindup(c.spec,c.attackRate??1)),samples});}
// 3. Hand motes (spellMotes) on a right hand at the origin, so every burst position is in the hand's frame. The renderer passes
// animateCharacter's pose, whose cast is spellPose(p,time).weight; dt is the frame step (times and steps kept unrounded: the
// emission clock accumulates them).
const moteCases=[
 {name:'fire 60 Hz',spec:'fire',lastAttack:10,hz:60,from:9.95,to:10.6,quality:1},{name:'lightning 144 Hz rate 1.4',spec:'lightning',lastAttack:10,attackRate:1.4,hz:144,from:9.99,to:10.3,quality:1},
 {name:'water 30 Hz',spec:'water',lastAttack:10,hz:30,from:9.9,to:10.5,quality:.3},{name:'darkness Q 60 Hz',spec:'darkness',lastAttack:5,lastAbility:10,hz:60,from:9.95,to:10.5,quality:1},
 {name:'leet 90 Hz',spec:'leet',lastAttack:10,hz:90,from:9.98,to:10.45,quality:1},{name:'fire, effects off',spec:'fire',lastAttack:10,hz:60,from:9.95,to:10.3,quality:0},
 {name:'fire twice (the clock restarts between casts)',spec:'fire',lastAttack:10,second:10.875,hz:60,from:9.95,to:11.3,quality:1},{name:'sword (melee)',spec:'sword',lastAttack:10,hz:60,from:9.95,to:10.3,quality:1}];
const motes=[];for(const c of moteCases){const hand=new T.Group();hand.updateMatrixWorld(true);const r={rightHand:hand};const frames=[];let prev=null;
 for(let f=0;c.from+f/c.hz<=c.to+1e-9;f++){const t=c.from+f/c.hz,dt=prev===null?0:t-prev;prev=t;const last=c.second!==undefined&&t>=c.second?c.second:c.lastAttack;
  const p=pilot(c.spec,{lastAttack:last,attackRate:c.attackRate??1,lastAbility:c.lastAbility}),cast=spellPose(p,t).weight,bursts=[];
  spellMotes(r,p,{cast},dt,c.quality,(pos,color,count,power)=>bursts.push({p:[r6(pos.x),r6(pos.y),r6(pos.z)],color,count,power}),t);frames.push({time:t,dt,lastAttack:last,cast:r6(cast),bursts});}
 const ref=c.lastAbility!==undefined?abilityPhrase(pilot(c.spec,{lastAbility:c.lastAbility,attackRate:c.attackRate??1}),c.lastAbility+.001):undefined;
 motes.push({name:c.name,spec:c.spec,attackRate:c.attackRate??1,ability:ref?{id:ref.id,start:ref.start,releaseAt:ref.releaseAt}:null,quality:c.quality,frames});}
// 4. Block cooldown dimming and the Ansatsuken parry flash (BlockCooldownTint) on a white Lambert part, a white unlit part and a
// part inside an excluded 'body-chips' group; colours are three's linear working values.
const tintCases=[];for(const [hp,blockCd,blockTime,parryAt,time] of [[100,0,0,-10,5],[100,3,0,-10,5],[100,3,0,-10,5.1],[100,3,0,-10,5.2333],[100,.2,0,-10,5.4],[100,.1,0,-10,5.05],[100,.24,0,-10,6.31],
 [100,3,.2,-10,5],[0,3,0,-10,5],[100,0,0,5,5],[100,0,0,5,5.05],[100,0,0,5,5.11],[100,0,0,5,5.2199],[100,0,0,5,5.23],[100,2,0,5,5.1],[0,0,0,5,5.05],[100,.15,0,-10,7.777]]){
 const group=new T.Group(),lit=new T.Mesh(new T.BoxGeometry(),new T.MeshLambertMaterial({color:0xffffff})),flat=new T.Mesh(new T.BoxGeometry(),new T.MeshBasicMaterial({color:0xffffff})),chips=new T.Group(),kept=new T.Mesh(new T.BoxGeometry(),new T.MeshBasicMaterial({color:0xffffff}));
 chips.name='body-chips';chips.add(kept);group.add(lit,flat,chips);const tint=new BlockCooldownTint();tint.update(group,{hp,blockCd,blockTime,arcade:{parryAt}},time);
 const c=m=>[r6(m.material.color.r),r6(m.material.color.g),r6(m.material.color.b)];
 tintCases.push({hp,blockCd,blockTime,parryAt,time,lit:c(lit),emissive:[r6(lit.material.emissive.r),r6(lit.material.emissive.g),r6(lit.material.emissive.b)],flat:c(flat),excluded:c(kept)});}
// 5. The class base offset of the camera-attached view (the first viewRoot.position write of a fresh view at rest, no sway yet).
const view=[];for(const spec of ['emperor','ansatsuken','sword','daggers','greatsword','shield','fire','leet','pistol','rifle','machinegun']){
 const rig=createCharacterRig('#70e1d0',undefined,true);markFirstPersonRig(rig);buildWeapon(rig.weapon,spec);const camera=new T.PerspectiveCamera(64,16/9,.08,400),viewRoot=new T.Group();camera.add(viewRoot);viewRoot.add(rig.group);
 let pos=null;const ps=viewRoot.position.set.bind(viewRoot.position);viewRoot.position.set=(x,y,z)=>{if(!pos)pos=[x,y,z];return ps(x,y,z);};
 poseFirstPersonView(rig,viewRoot,pilot(spec),1,1/60,false,null);view.push({spec,cls:spec==='emperor'||spec==='ansatsuken'?'fighter':WEAPONS[spec].class,base:pos.map(r6),yaw:r6(viewRoot.rotation.y),scale:r6(viewRoot.scale.x)});}
// 6. The Siren's weapon socket: renderer.ts:129 still runs weaponModifiers and enchant on r.weapon, but buildSiren hid it.
const siren=(()=>{const r=createCharacterRig('#70e1d0',undefined,true);buildWeapon(r.weapon,'siren');sirenify(r);const chips={multishot:2,ricochet:1,ember:2,poison:1,reach:1};
 weaponModifiers(r.weapon,pilot('siren',{chips}),1.2);enchantWeapon(r.weapon,['fire','poison'],1.2,chips);let meshes=0,shown=0;
 r.weapon.traverse(o=>{if(!o.isMesh)return;meshes++;let v=true;for(let a=o;a;a=a.parent)if(!a.visible)v=false;if(v)shown++;});return {chips,meshes,shown,socketVisible:r.weapon.visible};})();
fs.writeFileSync(path.join(root,'Tests/rig-dressing-parity.json'),JSON.stringify({commit:inventory.sourceCommit,three:'0.180.0',arcadeChargeSeconds:ARCADE.chargeSeconds,parryFlash:ARCADE.parryFlash,fpTune:FP_TUNE,
 body,charge,motes,tint:tintCases,view,siren})+'\n');
console.log('Exported',body.length,'body-chip,',charge.length,'spell-charge,',motes.length,'mote,',tintCases.length,'tint and',view.length,'view cases; Siren socket',siren.shown+'/'+siren.meshes,'shown');
